INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('75811369-28aa-4ed8-b388-a98314669e2a', '21feff02-016d-46e2-bb9d-c27495133b1b', '31. óra: A törtek szorzását alkalmazó feladatok megoldása', 'Törtrész kiszámítása és szöveges feladatok megoldása szorzással.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "ba136690-7937-4b65-888a-0a14383dde25", "text": "Mennyi 60-nak a 3/4 része? (60 * 3/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "45"}, {"id": "da223194-248c-4cc6-8166-3819f074de7d", "text": "Mennyi 100-nak az 1/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "98cc72f1-c2cf-4c88-a250-479f2b1c9d5e", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szeletet ettek meg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "183ae0ea-f434-4a48-8156-1b369393907b", "text": "Egy 24 szeletes tortának megették az 1/3-át. Hány szelet maradt?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "1835faff-f185-4107-9701-b63721672bdd", "text": "Egy szám törtrészének kiszámításához a számot megszorozzuk a törttel.", "type": "true-false", "options": [{"id": "b22ef036-20a6-4eb3-b76e-487f88286058", "text": "Igaz", "isCorrect": true}, {"id": "719cfb9f-7dec-4e4b-ba31-76f32095233e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "332f325c-7826-4762-a372-4c9d73bcac03", "text": "Mennyi 50-nek a 2/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "c9e85536-b262-4777-a264-6b83b738a267", "text": "Mennyi 1/2 óra percekben? (60 * 1/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()),
('b3146eb4-4609-4521-9476-712f7b58603c', '21feff02-016d-46e2-bb9d-c27495133b1b', '32. óra: Osztás törttel', 'Törttel való osztás szabálya: szorzás a reciprokával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "9d4031b4-1ecf-478f-8814-01a22b0f87c9", "text": "Hogyan osztunk törttel?", "type": "multiple-choice", "options": [{"id": "38514d4f-9e4f-4ba5-b38e-a96a690ada63", "text": "Az osztandót megszorozzuk az osztó reciprokával", "isCorrect": true}, {"id": "6bf8bdad-e4da-478f-8cb7-bebbd6abba92", "text": "Az osztandót elosztjuk a nevezővel", "isCorrect": false}, {"id": "10c9794c-fd17-40c1-b979-322cfc8460a2", "text": "Mindig 1-et kapunk", "isCorrect": false}, {"id": "757b1985-909a-4d30-8990-b2cc9595dc3d", "text": "A számlálókat elosztjuk egymással", "isCorrect": false}], "timeLimit": 15}, {"id": "4f1fb0a8-d35c-4e67-ab6d-62e12f7b8995", "text": "Mennyi 2/3 : 4/5? (2/3 * 5/4)", "type": "multiple-choice", "options": [{"id": "efa0cb3e-db83-4583-ba60-2ffd89b07b3b", "text": "10/12 (azaz 5/6)", "isCorrect": true}, {"id": "19467917-c6e4-4c97-b5ad-a5a1bd0c4d05", "text": "8/15", "isCorrect": false}, {"id": "2bab1f79-b9f4-4a81-b838-55b8a3a35fbb", "text": "6/8", "isCorrect": false}, {"id": "4344bc3a-255e-4d5f-85dc-96785c2a2bd7", "text": "15/8", "isCorrect": false}], "timeLimit": 15}, {"id": "1769616a-1717-49b3-b61d-bb62a3fea159", "text": "Mennyi 1/2 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "5d46c450-477d-48ee-b45a-b8601a87b49a", "text": "Ha egy számot 1/2-del osztunk, az eredmény megegyezik a szám 2-vel való szorzatával.", "type": "true-false", "options": [{"id": "ff04aaea-a367-4865-b081-2edfdef28e2a", "text": "Igaz ( : 1/2 = * 2)", "isCorrect": true}, {"id": "560b6cfa-36ff-46e7-92aa-f5183845170d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ed9cb565-77f5-4529-87bc-15c3398d8483", "text": "Mennyi 6 : 1/3? (6 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "ff0c1d72-4836-4bdd-a01b-9d1d6ce582ff", "text": "Törttel való osztáskor az osztandó nem változik, csak az osztót fordítjuk meg.", "type": "true-false", "options": [{"id": "0ba2c847-10b1-4d8b-9d3c-dede49b8a651", "text": "Igaz", "isCorrect": true}, {"id": "fa70fc83-27a8-41ab-b9cd-e88a30020713", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "14e782f8-48b0-4cbe-8258-6de5a411dbc7", "text": "Mennyi 3/4 : 3/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}]'::jsonb, true, NOW()),
('4ea58a34-3280-42e5-89ed-f8ea9adcbd42', '21feff02-016d-46e2-bb9d-c27495133b1b', '33. óra: Hétköznapi problémák megoldása törtek osztásának felhasználásával', 'Szöveges feladatok mérésekkel, átdarabolásokkal, törtek osztásával.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "0f4e2025-13e7-4587-b510-770b663c7a5e", "text": "Hány 1/4 literes pohár tölthető meg 3 liter almaléből? (3 : 1/4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "683dfee9-a931-404a-8427-f5b24549d90e", "text": "Hány 1/2 kg-os csomag képezhető 5 kg cukorból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "eb69398f-9c57-4ada-98e7-f21490bda58b", "text": "Egy 6 méteres szalagból 3/4 méteres darabokat vágunk. Hány darabot kapunk? (6 : 3/4 = 6 * 4/3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "a866c268-4c61-4f8a-9407-143ad2f00eca", "text": "Törtek osztásakor az eredmény lehet nagyobb az eredeti osztandónál, ha az osztó 1-nél kisebb tört.", "type": "true-false", "options": [{"id": "67bfaebc-1c9c-4c6d-a41b-45019cd3f5c7", "text": "Igaz", "isCorrect": true}, {"id": "d6342216-e819-4c08-a38c-2f99b34a1738", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "256447e6-3591-4126-9fae-3622ae7a664c", "text": "Hány 1/5 méteres darab vágható ki 2 méter anyagból?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "456a224e-0b31-40e9-b53f-966b6db700b7", "text": "A szöveges feladatoknál az adatok lejegyzése és a mértékegységek egyeztetése elengedhetetlen.", "type": "true-false", "options": [{"id": "6e0b415b-956d-4a41-a976-b91513b8a82e", "text": "Igaz", "isCorrect": true}, {"id": "9da3c649-8c95-4471-89fd-4da0a781e219", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "15bd3510-6b56-4393-b8f7-d162a615646a", "text": "Mennyi 4 : 2/3? (4 * 3/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()),
('3d49e327-9e90-4369-964a-e52d67857d86', '21feff02-016d-46e2-bb9d-c27495133b1b', '34. óra: Gyakorlóóra', 'A törtek szorzásának és osztásának rögzítése, feladatok gyakorlása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "b7b7aa7e-a939-4f64-ba7e-32f286e7fe18", "text": "Mennyi 3/5 * 5/3?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "044c8a6e-1e0e-4c7a-a2c9-3de190c6c3f2", "text": "Mennyi 4/7 : 2/7? (4/7 * 7/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "498910e7-13a5-4e91-a663-15eee3b55025", "text": "Melyik állítás igaz?", "type": "multiple-choice", "options": [{"id": "907f530f-f8da-42d3-8e4e-e9bcd756ba3b", "text": "Két 1-nél kisebb pozitív tört szorzata kisebb mindkét tényezőnél", "isCorrect": true}, {"id": "75557ff4-f2dc-4523-86eb-9566fd6e3a57", "text": "A szorzat mindig nagyobb a tényezőknél", "isCorrect": false}, {"id": "bf2584df-a3e9-4d69-9c71-3ff7a67c745e", "text": "Az osztás mindig kisebb számot ad", "isCorrect": false}, {"id": "77744782-04b6-4b90-85f9-0d9fbd467d8c", "text": "Nincs reciproka a 4/5-nek", "isCorrect": false}], "timeLimit": 15}, {"id": "db19a799-0f95-4546-adf5-ce10a612fb05", "text": "Mennyi 5/6 * 12? (5 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "ca9b3bf1-9c22-4bec-b219-5f063b1693a1", "text": "A 2/3 osztva 1/3-dal 2-t ad.", "type": "true-false", "options": [{"id": "1439b366-aaf7-4d4e-b8f9-ce71a0c623d2", "text": "Igaz", "isCorrect": true}, {"id": "9dd5241f-0c05-40ba-98f8-7558e5497bef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "27a792ca-c360-48c2-84c3-92455ed394d6", "text": "Mennyi 3/8 : 3/8?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "0c404204-33f7-48ca-a2c7-f7ca7c34a816", "text": "Mennyi 1/4 * 4/5?", "type": "multiple-choice", "options": [{"id": "e6881ed6-45fe-49c8-ad29-f984ffeb9d05", "text": "1/5", "isCorrect": true}, {"id": "7796c578-d561-424c-bc13-fb7a66c3772e", "text": "4/20", "isCorrect": false}, {"id": "5b65dd8a-6b29-4eb3-a258-969779645afc", "text": "1/20", "isCorrect": false}, {"id": "417aa085-da1e-46c6-be30-a6fce8e33bb8", "text": "4/9", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('0eee44dc-f066-403c-9822-5672af8bcbfd', '21feff02-016d-46e2-bb9d-c27495133b1b', '35. óra: Számonkérés', 'Számonkérés a közönséges törtek műveleteiből (10 kérdés).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "15baf398-fcbf-4173-aa9e-ac72c6cc99d9", "text": "1. Mennyi 2/5 + 1/5?", "type": "multiple-choice", "options": [{"id": "118a151f-a740-4585-b25a-6ac7fe8810dd", "text": "3/5", "isCorrect": true}, {"id": "6849df55-b34f-481c-be27-68a511b665fa", "text": "3/10", "isCorrect": false}, {"id": "666213d2-a150-4c64-8d2b-96a3af1db643", "text": "2/10", "isCorrect": false}, {"id": "cca91bee-2b83-4915-a4e2-e7d2524bc572", "text": "1/5", "isCorrect": false}], "timeLimit": 15}, {"id": "2d7e1116-efcb-470f-b82a-269e841ccc41", "text": "2. Mennyi 3/4 - 1/2? (3/4 - 2/4)", "type": "multiple-choice", "options": [{"id": "9cf944e5-f75a-486f-897d-07b494b45346", "text": "1/4", "isCorrect": true}, {"id": "c01b9343-0f24-4ce9-960b-939a69c24373", "text": "2/2", "isCorrect": false}, {"id": "6bd2da8e-6bf3-48ba-b451-9479a428fd58", "text": "1/2", "isCorrect": false}, {"id": "ba69c7eb-3b6f-469d-a1f9-45e0ad365d37", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "dd50b587-c84e-4f60-8fb1-f651f17acd3f", "text": "3. Mennyi 2/3 * 3/4?", "type": "multiple-choice", "options": [{"id": "3f0af8a0-dd46-4c37-abd1-479ecaf51e35", "text": "6/12 (azaz 1/2)", "isCorrect": true}, {"id": "4a3cb4da-93ef-4d6a-b9c7-9b6bf208e041", "text": "5/7", "isCorrect": false}, {"id": "654e7972-53a8-4b34-acb7-ce3c6390b951", "text": "6/7", "isCorrect": false}, {"id": "983f7c11-0ad1-4374-b174-73003049dd55", "text": "2/4", "isCorrect": false}], "timeLimit": 15}, {"id": "119b5888-4b60-4ebc-98f3-1802d51b2625", "text": "4. Mennyi 1/2 : 1/4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "628bb845-2d46-4a17-bbbd-dbcde9a36ad5", "text": "5. Mi a 7/8 reciproka?", "type": "multiple-choice", "options": [{"id": "d0231204-6592-4bd1-a769-f90a2ccefd95", "text": "8/7", "isCorrect": true}, {"id": "26854606-aa6e-4f07-8cd3-b35b7fae336b", "text": "-7/8", "isCorrect": false}, {"id": "942fa37c-f0dd-4c31-a89e-83d4043502b1", "text": "1/7", "isCorrect": false}, {"id": "0d4a1e3b-14d9-42e3-b824-a9c9807d46d6", "text": "7/8", "isCorrect": false}], "timeLimit": 15}, {"id": "61bf68d3-729f-4a64-9354-816ebfbc98dc", "text": "6. Mennyi 40-nek a 3/5 része?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "e3573899-b32c-458a-8b95-7bc9ebd92eb4", "text": "7. Egy szám és reciproka szorzata 1.", "type": "true-false", "options": [{"id": "02d50998-1ef2-42c7-a4b3-4e1db046ff3e", "text": "Igaz", "isCorrect": true}, {"id": "7be1abc8-8481-4647-bf70-4b34fdbafa71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "95075224-b6de-45f9-8af8-e4044dadbd21", "text": "8. Mennyi 5 : 1/2?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "d34c80c5-e749-4f01-b543-476aa3ed9338", "text": "9. A törtek szorzásakor a számlálót a számlálóval, a nevezőt a nevezővel szorozzuk.", "type": "true-false", "options": [{"id": "eae26c6b-fd47-444c-a45f-7710e3681630", "text": "Igaz", "isCorrect": true}, {"id": "239e8039-7edd-4e70-82e1-06aec1c35bed", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "78a078f6-19ff-4bda-829d-b4aa8bab2737", "text": "10. Hány negyedből áll 3 egész?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()),
('1ec69f99-dbba-4f0b-bb6d-85234b26af13', '21feff02-016d-46e2-bb9d-c27495133b1b', '36. óra: Matematikai játékok', 'Matematikai társasjátékok, stratégiák törtekkel, csoport- és páros munka.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "5137d573-618f-4018-8320-3cd84fba9895", "text": "Melyik állítás igaz a matematikai társasjátékokról?", "type": "multiple-choice", "options": [{"id": "f97c87a2-9678-46d9-a0dd-2ceb0ae16080", "text": "Fejlesztik a számolási gyorsaságot és a logikai stratégiát", "isCorrect": true}, {"id": "1f5be37b-1434-4c21-94c9-28387954e413", "text": "Nincs közük a matematikához", "isCorrect": false}, {"id": "0c4e1b14-5507-4443-b36a-d6d857b71e54", "text": "Kizárólag szerencse kell hozzájuk", "isCorrect": false}, {"id": "d93e4cb9-503d-4add-8f07-785774f68b75", "text": "Tiltható az együttműködés", "isCorrect": false}], "timeLimit": 15}, {"id": "2c0b3a56-6d72-4afc-ba5c-df7efcc28721", "text": "A tört domino játékban az egyenlő értékű törteket illesztjük össze.", "type": "true-false", "options": [{"id": "2b2e8553-96d4-4f3f-877b-5ed9284c5b16", "text": "Igaz", "isCorrect": true}, {"id": "58b9d87f-ad3c-4a38-9fcd-fbef3799866b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e84f8855-f3c0-4045-80de-75ef5aeacd00", "text": "Melyik tört felel meg a 0,5 tizedes törtnek?", "type": "multiple-choice", "options": [{"id": "cfc37068-96ac-4cac-8e78-64d77b5a2bb3", "text": "1/2", "isCorrect": true}, {"id": "25a79a63-53cc-49da-a4f9-12f94fe66024", "text": "1/5", "isCorrect": false}, {"id": "b799b94f-2681-4c75-aebe-ae52b974e507", "text": "2/5", "isCorrect": false}, {"id": "6fd623e1-46f2-46cb-82c8-aa129e00df35", "text": "5/2", "isCorrect": false}], "timeLimit": 15}, {"id": "85db8849-0b3e-4602-8dfe-49ea91bc5744", "text": "Melyik tört felel meg a 0,25-nek?", "type": "multiple-choice", "options": [{"id": "5058cfc9-4a38-41f7-b21f-769b170014a1", "text": "1/4", "isCorrect": true}, {"id": "3f887cfe-58c4-4d42-9cdb-9d009d5f8168", "text": "1/2", "isCorrect": false}, {"id": "7c6c8711-bcab-4739-9a5a-188ec459f6c2", "text": "2/5", "isCorrect": false}, {"id": "916f8d8c-e8d6-4211-8f95-fd3521ef4078", "text": "3/4", "isCorrect": false}], "timeLimit": 15}, {"id": "22bff2da-98ae-417e-9282-49e3629e4adf", "text": "A 3/4 tizedes tört alakja 0,75.", "type": "true-false", "options": [{"id": "887bd9ec-a042-4b7d-b766-d541ed14b81e", "text": "Igaz", "isCorrect": true}, {"id": "2c11514e-9572-4d3c-99a2-fb381fc7eb48", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1f1fccd3-c8b4-4c94-85ca-b28cf43ac21a", "text": "Mennyi 0,2 közönséges tört alakban legegyszerűbb formában?", "type": "multiple-choice", "options": [{"id": "41d0f40f-1b22-4057-a7d3-db8d071d360c", "text": "1/5", "isCorrect": true}, {"id": "e6fc82e9-b793-45b6-ae80-1c99ae2e7974", "text": "2/10", "isCorrect": false}, {"id": "c14016bb-7310-473a-a125-bd46de998c03", "text": "1/2", "isCorrect": false}, {"id": "d43f69ad-a4fc-47f4-b4ff-fa3bbb7a0cdb", "text": "2/5", "isCorrect": false}], "timeLimit": 15}, {"id": "eb41e270-7128-42d7-a10e-64686535f80f", "text": "A tört-bingó játékban a válaszok gyors és pontos kiszámítása a nyerő stratégia.", "type": "true-false", "options": [{"id": "207bad62-9c8d-4fd0-b77b-68813c3e6435", "text": "Igaz", "isCorrect": true}, {"id": "00e373b2-1d22-417c-88f9-6987b8aa1b11", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('f628b66d-9ba6-4cee-81ea-977d860ead2c', '21feff02-016d-46e2-bb9d-c27495133b1b', '37. óra: Mit tanultunk a tizedes törtekről?', 'Tizedes törtek helyi értékei, összeadása és kivonása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "3d377f65-84ae-41c3-91a0-10f06dc2011d", "text": "Mi a tizedesvessző utáni első helyi érték neve?", "type": "multiple-choice", "options": [{"id": "93b12254-1d14-4083-9a64-522227a23f73", "text": "Tizedek", "isCorrect": true}, {"id": "ec7e1310-20ac-4a15-b690-4ee5a2c59f54", "text": "Századok", "isCorrect": false}, {"id": "6a843efd-33af-497f-9917-4ae1d2ed0271", "text": "Ezredeket", "isCorrect": false}, {"id": "cc12efaf-6cb3-43b7-adf0-2d822c8fc070", "text": "Egyesek", "isCorrect": false}], "timeLimit": 15}, {"id": "ae0331a3-caba-4eee-8a8c-f8aab38cac2a", "text": "Mi a tizedesvessző utáni második helyi érték neve?", "type": "multiple-choice", "options": [{"id": "9dd3a1b8-bdb8-4fed-a6e7-e8952d4ab2fe", "text": "Századok", "isCorrect": true}, {"id": "04de5181-67ef-4e9b-9815-489b278d40cc", "text": "Tizedek", "isCorrect": false}, {"id": "df25206d-1589-4da5-8613-64a85adf3cb2", "text": "Ezredek", "isCorrect": false}, {"id": "15a0fcc0-f652-4fa9-9ca3-d7c86c2e0879", "text": "Tízesek", "isCorrect": false}], "timeLimit": 15}, {"id": "99f4c05b-b443-406f-bada-1b116a5b1fc0", "text": "Mennyi 3,45 + 2,13?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5.58"}, {"id": "17ed97fd-26b4-4f97-a8c3-1397ec95319c", "text": "Mennyi 7,8 - 3,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.3"}, {"id": "4f07208d-0d67-4556-9dc8-8056bc7f6fa0", "text": "Tizedes törtek írásbeli összeadásakor a tizedesvesszőknek egymás alá kell kerülniük.", "type": "true-false", "options": [{"id": "70031d5f-3107-444e-9a40-82ceab60220c", "text": "Igaz", "isCorrect": true}, {"id": "f9ca65f0-fcde-4605-9a2c-7cf9c5590aa5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "59f944b8-54d7-4bc9-9ad0-7d704a1e72ed", "text": "Mennyi 5,6 + 4,4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "89430252-49ab-43e2-9f86-a6e2222a3d2b", "text": "Melyik szám nagyobb: 4,05 vagy 4,5?", "type": "multiple-choice", "options": [{"id": "16c46ce3-6ec5-49dd-9a95-b0abed2bac30", "text": "4,5 (mert 4,5 = 4,50)", "isCorrect": true}, {"id": "4fb5450c-e106-4930-87a7-c57766028fe4", "text": "4,05", "isCorrect": false}, {"id": "ac081c5f-8d35-4069-9776-3d3019b73b45", "text": "Egyenlőek", "isCorrect": false}, {"id": "6e5ce540-4aa0-4954-930b-fe7fe939ba72", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('4df3dbd5-2ce3-4df8-9714-a9fe54d61cb7', '21feff02-016d-46e2-bb9d-c27495133b1b', '38. óra: Szorzás tizedes törttel', 'Tizedes tört szorzása egész számmal és tizedes törttel, vesszőhely meghatározása.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "ea77089d-07b8-49cf-bc06-e83d1ee6cbbe", "text": "Hogyan határozzuk meg a tizedesjegyek számát két tizedes tört szorzatában?", "type": "multiple-choice", "options": [{"id": "5a0db28b-ed9c-4e79-86a9-e2ab50df0239", "text": "A tényezők tizedesjegyeinek számát összeadjuk", "isCorrect": true}, {"id": "761cddcb-2745-48f0-a6f0-e030fa95dab4", "text": "A nagyobbik tényező tizedesjegyeit vesszük", "isCorrect": false}, {"id": "2ff66125-8403-4ce9-9cce-53fb6b2dbdce", "text": "Mindig 1 tizedesjegy lesz", "isCorrect": false}, {"id": "8e251f71-a070-4330-bcdd-151865181939", "text": "Nem lesz tizedesjegy", "isCorrect": false}], "timeLimit": 15}, {"id": "402c3c88-4e01-43f2-8e7f-c2e39ca5ba6c", "text": "Mennyi 0,3 * 0,2? (3*2 = 6, 2 tizedesjegy)", "type": "multiple-choice", "options": [{"id": "12e72bb0-1e9e-4772-95cc-67f849ea2d14", "text": "0,06", "isCorrect": true}, {"id": "7ef8d96c-abac-4212-b7f7-6a55bb92ce0c", "text": "0,6", "isCorrect": false}, {"id": "740a71a3-f6bb-435c-8004-ad2cad3f1e67", "text": "6,0", "isCorrect": false}, {"id": "56ee8074-46a8-4af5-8783-182f5f021ccf", "text": "0,006", "isCorrect": false}], "timeLimit": 15}, {"id": "0c1ae7c7-cf1e-4cd1-a838-d9ce97ed7010", "text": "Mennyi 2,5 * 4?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "20e61e5c-565a-4bc3-90e1-f709f795d639", "text": "Mennyi 1,2 * 0,5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.6"}, {"id": "badcfdaf-c9cf-4c75-9b94-36a6c89e6762", "text": "Ha egy tizedes törtet 10-zel szorzunk, a tizedesvessző egy hellyel jobbra lép.", "type": "true-false", "options": [{"id": "225c3263-7527-4ce2-a0f6-631f1895cb5e", "text": "Igaz", "isCorrect": true}, {"id": "6f152914-ee1d-4fa8-807a-d659efaa9547", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fa5f2b1b-f16a-4155-8536-ebf22460ab66", "text": "Mennyi 3,45 * 100?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "345"}, {"id": "78d747f8-c7e5-4e3a-a9ec-94187a81b2b4", "text": "Mennyi 0,1 * 0,1?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0.01"}]'::jsonb, true, NOW()),
('6d318292-6a9a-49bc-b27a-61313b57f09e', '21feff02-016d-46e2-bb9d-c27495133b1b', '39. óra: Osztás tizedes törttel', 'Tizedes törttel való osztás szabálya, osztó egész számmá alakítása (bővítés 10-zel, 100-zal).', 'Matematika', '6. osztály', 'Törtek', '[{"id": "3f2b0684-2d3e-4916-9ed8-ed2b75fd9aaf", "text": "Mit teszünk tizedes törttel való osztáskor először?", "type": "multiple-choice", "options": [{"id": "be132486-1acb-4fdc-bec1-059ca36ca40b", "text": "Az osztandót és az osztót is megszorozzuk 10-zel/100-zal, hogy az osztó egész szám legyen", "isCorrect": true}, {"id": "1ca4506a-e0ba-4a86-b710-502e6ad2a483", "text": "Elhagyjuk a tizedesvesszőt az osztandóból", "isCorrect": false}, {"id": "c1b89f44-3535-48b0-a3cd-c6624c685c23", "text": "Kivonjuk az osztót az osztandóból", "isCorrect": false}, {"id": "00e10bef-0b19-4d6d-9fd8-84ef0e6f0f60", "text": "Csak az osztót szorozzuk meg", "isCorrect": false}], "timeLimit": 15}, {"id": "e44165f2-4649-4475-aead-73d3c1871d4d", "text": "Mennyi 2,4 : 0,6? (24 : 6)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "62797965-5267-425f-8cfa-f13adcbf72a6", "text": "Mennyi 1,5 : 0,3? (15 : 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "7d497882-0114-4f6f-a305-334f2a131d14", "text": "Ha egy tizedes törtet 10-zel osztunk, a tizedesvessző 1 hellyel balra lép.", "type": "true-false", "options": [{"id": "bd869cb2-0b4d-48a8-a418-0a9133e57901", "text": "Igaz", "isCorrect": true}, {"id": "e062db7b-f0a9-4b66-8cb8-de7cab417fc0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f5835c26-95ba-462f-a6c7-cd95e7f0b8b1", "text": "Mennyi 45,6 : 10?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.56"}, {"id": "525f4c2f-40fd-4101-afe6-d4ed219c971e", "text": "Mennyi 3,6 : 0,1? (36 : 1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "e2b3b6a4-4c78-4a77-a613-42879000c991", "text": "A tizedes törtte