('b92ff86c-252d-4e33-b99b-2c783f46ebb4', '21feff02-016d-46e2-bb9d-c27495133b1b', '40. óra: Hétköznapi problémák megoldása tizedes törtek szorzásának, osztásának felhasználásával', 'Vásárlási, mértékegységes és szöveges feladatok.', 'Matematika', '6. osztály', 'Törtek', '[{"id": "bbb42e13-087e-4ec0-8683-1266c4c59bb4", "text": "1 kg sajt ára 3200 Ft. Mennyibe kerül 0,5 kg sajt? (3200 * 0,5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1600"}, {"id": "406e0500-38e4-4115-bcd3-8df2a531c587", "text": "Peti 3,5 kg almát vett 400 Ft/kg áron. Hány Ft-ot fizetett?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1400"}, {"id": "07e15864-042a-44c2-9175-8752c826f5d8", "text": "Egy 4,8 méteres lécet 4 egyenlő darabra vágunk. Hány méter egy darab?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "e000924f-a959-49f4-85ca-c954344e2205", "text": "Ha 0,25 liter üdítő 150 Ft, akkor 1 liter üdítő (4 * 0,25) 600 Ft-ba kerül.", "type": "true-false", "options": [{"id": "28e69786-f5fd-49c5-85e2-99549351969f", "text": "Igaz", "isCorrect": true}, {"id": "523cf248-a414-4b0b-a8b1-2e2e71b34efd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "d3d937c7-160d-4757-a7e3-1d502a12e481", "text": "Hány liter benzin fér a tankba 12000 Ft-ért, ha 1 liter benzin 600 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "baf28ad5-6119-4c4e-8911-14fc2bf2886c", "text": "A becslés segít ellenőrizni, hogy a tizedesvesszőt jó helyre tettük-e a végeredményben.", "type": "true-false", "options": [{"id": "b4ce73ad-60b8-424c-8844-e7dc67e2a718", "text": "Igaz", "isCorrect": true}, {"id": "dfb46649-bcae-4f2f-b8e8-0513624621c7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2a7ca3e9-1703-4a6d-9b9a-66c64bd56b2c", "text": "Mennyi 1,5 kg narancs ára, ha 1 kg 800 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1200"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;